let __v_81 = pyrt::literals::decode("{\"$tuple\":[\"covid\",\"coronavirus\",\"lateral flow\",\"pcr\",\"mot\",\"theory\",\"driving test\",\"eye test\",\"blood test\",\"urine test\",\"hearing test\",\"smear\",\"cervical\",\"chlamydia\",\"sti\",\"std\",\"thyroid\",\"diabetes\",\"allergy\",\"intolerance\",\"paternity\",\"dna\",\"quiz\",\"exam\",\"revision\",\"mock\",\"interview\",\"coding\",\"swab\",\"skin prick\"]}")?;
